<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'stock.view')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php';
require_once __DIR__ . '/_inventory.php';
$db = Database::getInstance();
$role = $user['role_system'];
$search = trim((string) ($_GET['q'] ?? ''));
$category = trim((string) ($_GET['category'] ?? ''));
$conditions = ['1 = 1'];
$params = [];
if ($search !== '') { $conditions[] = '(medicine_name LIKE ? OR bar_code LIKE ? OR shelf LIKE ?)'; $pattern = '%' . $search . '%'; array_push($params, $pattern, $pattern, $pattern); }
if ($category !== '') { $conditions[] = 'category = ?'; $params[] = $category; }
$where = 'WHERE ' . implode(' AND ', $conditions);
$total = (int) $db->fetchColumn("SELECT COUNT(*) FROM stock $where", $params);
$page = max(1, (int) ($_GET['page'] ?? 1));
$perPage = 20;
$pages = max(1, (int) ceil($total / $perPage));
$page = min($page, $pages);
$offset = ($page - 1) * $perPage;
$products = $db->fetchAll("SELECT id, bar_code, medicine_name, category, shelf, actual_quantity, sell_type, actual_price, selling_price, seuil, status FROM stock $where ORDER BY medicine_name LIMIT $perPage OFFSET $offset", $params);
$categories = $db->fetchAll('SELECT DISTINCT category FROM stock ORDER BY category');
$flash = $_SESSION['flash_message'] ?? null; unset($_SESSION['flash_message']);
$pageUrl = static fn(int $target): string => app_route_url('stock', $role) . '?' . http_build_query(['q' => $search, 'category' => $category, 'page' => $target]);
?>
<section class="space-y-5">
    <header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold text-blue-800">Magasinier</p><h1 class="mt-1 text-2xl font-bold text-slate-900">État du stock</h1><p class="mt-1 text-sm text-slate-600"><?= number_format($total, 0, ',', ' ') ?> référence(s)</p></div><div class="flex flex-wrap gap-2"><?php if (userCan($user, 'stock.create')): ?><a href="<?= inventoryEscape(app_route_url('stock/ajouter')) ?>" class="inline-flex items-center gap-2 rounded-md bg-green-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-green-800"><i data-feather="plus" class="h-4 w-4"></i> Ajouter produit</a><?php endif; ?><?php if (userCan($user, 'flux.entrees')): ?><a href="<?= inventoryEscape(app_route_url('stock/entrees')) ?>" class="inline-flex items-center gap-2 rounded-md border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700"><i data-feather="download" class="h-4 w-4"></i> Entrée</a><?php endif; ?><?php if (userCan($user, 'flux.sorties')): ?><a href="<?= inventoryEscape(app_route_url('stock/sorties')) ?>" class="inline-flex items-center gap-2 rounded-md border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700"><i data-feather="upload" class="h-4 w-4"></i> Sortie</a><?php endif; ?></div></header>
    <?php if ($flash): ?><div role="status" class="rounded-md border px-4 py-3 text-sm <?= ($flash['type'] ?? '') === 'success' ? 'border-green-200 bg-green-50 text-green-800' : 'border-red-200 bg-red-50 text-red-800' ?>"><?= inventoryEscape($flash['text'] ?? '') ?></div><?php endif; ?>
    <form method="get" action="<?= inventoryEscape(app_url('router.php')) ?>" class="grid gap-3 rounded-md border border-slate-200 bg-white p-4 sm:grid-cols-[minmax(12rem,1fr)_14rem_auto_auto] sm:items-end"><input type="hidden" name="route" value="<?= inventoryEscape($role . '/stock') ?>"><label class="space-y-1 text-sm font-medium text-slate-700">Recherche<input name="q" value="<?= inventoryEscape($search) ?>" placeholder="Produit, code-barres ou emplacement" class="w-full rounded-md border border-slate-300 px-3 py-2 font-normal"></label><label class="space-y-1 text-sm font-medium text-slate-700">Catégorie<select name="category" class="w-full rounded-md border border-slate-300 bg-white px-3 py-2 font-normal"><option value="">Toutes</option><?php foreach ($categories as $item): ?><option value="<?= inventoryEscape($item['category']) ?>" <?= $category === $item['category'] ? 'selected' : '' ?>><?= inventoryEscape($item['category']) ?></option><?php endforeach; ?></select></label><button class="rounded-md border border-slate-300 bg-white px-4 py-2 text-sm font-medium hover:bg-slate-50">Filtrer</button><?php if ($search !== '' || $category !== ''): ?><a href="<?= inventoryEscape(app_route_url('stock')) ?>" class="px-3 py-2 text-sm text-slate-600">Effacer</a><?php endif; ?></form>
    <div class="overflow-x-auto rounded-md border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Produit</th><th class="px-4 py-3">Catégorie</th><th class="px-4 py-3">Emplacement</th><th class="px-4 py-3 text-right">Disponible</th><th class="px-4 py-3 text-right">Seuil</th><th class="px-4 py-3">État</th><th class="px-4 py-3 text-right">Prix vente</th><th class="px-4 py-3">Actions</th></tr></thead><tbody class="divide-y divide-slate-100">
        <?php if (!$products): ?><tr><td colspan="8" class="px-4 py-12 text-center text-slate-500">Aucun produit ne correspond à ces critères.</td></tr><?php else: foreach ($products as $product): ?>
            <?php $low = (float) $product['actual_quantity'] <= (float) $product['seuil']; ?>
            <tr class="hover:bg-slate-50"><td class="px-4 py-3"><div class="font-semibold text-slate-900"><?= inventoryEscape($product['medicine_name']) ?></div><div class="text-xs text-slate-500">Code <?= (int) $product['bar_code'] ?> · <?= inventoryEscape($product['sell_type']) ?></div></td><td class="px-4 py-3"><?= inventoryEscape($product['category']) ?></td><td class="px-4 py-3"><?= inventoryEscape($product['shelf'] ?: '—') ?></td><td class="px-4 py-3 text-right font-semibold <?= $low ? 'text-amber-700' : 'text-slate-900' ?>"><?= number_format((float) $product['actual_quantity'], 2, ',', ' ') ?></td><td class="px-4 py-3 text-right text-slate-600"><?= number_format((float) $product['seuil'], 0, ',', ' ') ?></td><td class="px-4 py-3"><span class="rounded-full px-2.5 py-1 text-xs font-medium <?= $low ? 'bg-amber-100 text-amber-800' : 'bg-green-100 text-green-800' ?>"><?= $low ? 'À surveiller' : inventoryEscape($product['status']) ?></span></td><td class="whitespace-nowrap px-4 py-3 text-right"><?= number_format((float) $product['selling_price'], 0, ',', ' ') ?> FBu</td><td class="whitespace-nowrap px-4 py-3"><div class="flex gap-2"><?php if (userCan($user, 'flux.entrees')): ?><a title="Entrée" aria-label="Entrée de stock pour <?= inventoryEscape($product['medicine_name']) ?>" href="<?= inventoryEscape(app_route_url('stock/entrees')) ?>?product_id=<?= (int) $product['id'] ?>" class="rounded border border-slate-300 p-2 text-green-800"><i data-feather="download" class="h-4 w-4"></i></a><?php endif; ?><?php if (userCan($user, 'flux.sorties')): ?><a title="Sortie" aria-label="Sortie de stock pour <?= inventoryEscape($product['medicine_name']) ?>" href="<?= inventoryEscape(app_route_url('stock/sorties')) ?>?product_id=<?= (int) $product['id'] ?>" class="rounded border border-slate-300 p-2 text-rose-700"><i data-feather="upload" class="h-4 w-4"></i></a><?php endif; ?></div></td></tr>
        <?php endforeach; endif; ?>
    </tbody></table></div>
    <?php if ($pages > 1): ?><nav class="flex items-center justify-between"><span class="text-sm text-slate-600">Page <?= $page ?> sur <?= $pages ?></span><div class="flex gap-2"><?php if ($page > 1): ?><a class="rounded border px-3 py-2 text-sm" href="<?= inventoryEscape($pageUrl($page - 1)) ?>">Précédent</a><?php endif; ?><?php if ($page < $pages): ?><a class="rounded border px-3 py-2 text-sm" href="<?= inventoryEscape($pageUrl($page + 1)) ?>">Suivant</a><?php endif; ?></div></nav><?php endif; ?>
</section>